"""Thin provider adapters. Keep every vendor-specific line in here.

complete(provider, model_id, messages, temperature, max_tokens) -> {text, usage, reported_model, finish_reason}

Supported out of the box: any OpenAI-compatible chat endpoint ("openai", with optional base_url),
and Anthropic. Add others by registering a function in ADAPTERS.
Credentials come from environment variables only. Never commit keys.
"""
import os


class RetryableError(Exception):
    pass


def _openai_compatible(model_id, messages, temperature, max_tokens, base_url=None, api_key_env="OPENAI_API_KEY"):
    try:
        from openai import OpenAI, RateLimitError, APIStatusError
    except ImportError as e:
        raise RuntimeError("pip install openai") from e
    client = OpenAI(api_key=os.environ[api_key_env], base_url=base_url)
    try:
        r = client.chat.completions.create(
            model=model_id, messages=messages, temperature=temperature, max_tokens=max_tokens
        )
    except RateLimitError as e:
        raise RetryableError(str(e)) from e
    except APIStatusError as e:
        if e.status_code >= 500:
            raise RetryableError(str(e)) from e
        raise
    c = r.choices[0]
    return {
        "text": c.message.content or "",
        "usage": r.usage.model_dump() if r.usage else None,
        "reported_model": r.model,
        "finish_reason": c.finish_reason,
    }


def _anthropic(model_id, messages, temperature, max_tokens, **_):
    try:
        import anthropic
    except ImportError as e:
        raise RuntimeError("pip install anthropic") from e
    client = anthropic.Anthropic(api_key=os.environ["ANTHROPIC_API_KEY"])
    system = "\n".join(m["content"] for m in messages if m["role"] == "system") or None
    convo = [m for m in messages if m["role"] != "system"]
    try:
        r = client.messages.create(
            model=model_id,
            max_tokens=max_tokens,
            temperature=temperature,
            system=system if system else anthropic.NOT_GIVEN,
            messages=convo,
        )
    except anthropic.RateLimitError as e:
        raise RetryableError(str(e)) from e
    except anthropic.APIStatusError as e:
        if e.status_code >= 500:
            raise RetryableError(str(e)) from e
        raise
    text = "".join(b.text for b in r.content if getattr(b, "type", "") == "text")
    return {
        "text": text,
        "usage": {"input_tokens": r.usage.input_tokens, "output_tokens": r.usage.output_tokens},
        "reported_model": r.model,
        "finish_reason": r.stop_reason,
    }


ADAPTERS = {
    "openai": _openai_compatible,
    "anthropic": _anthropic,
    # "openrouter": lambda *a, **k: _openai_compatible(*a, base_url="https://openrouter.ai/api/v1", api_key_env="OPENROUTER_API_KEY", **k),
}


def complete(provider, model_id, messages, temperature, max_tokens, **kwargs):
    if provider not in ADAPTERS:
        raise ValueError(f"unknown provider {provider!r}; add it to providers.ADAPTERS")
    return ADAPTERS[provider](model_id, messages, temperature, max_tokens, **kwargs)
